// Where the call summaries land. Swap for hello@freebusinessregistration.com
// once FBR is a live client rather than a demo.
const TEAM_INBOX = 'saifarshad674@gmail.com';

// Retell has shifted this payload shape between versions, so read defensively.
const body = $input.first().json.body ?? $input.first().json;
const tool = body.name ?? body.function_name ?? body.tool_name ?? 'unknown_tool';
const args = body.args ?? body.arguments ?? body.parameters ?? {};
const call = body.call ?? {};

// What each tool means to a human reading the subject line at 7am.
const LABELS = {
  start_registration:        ['NEW REGISTRATION', 'Formations'],
  log_service_interest:      ['SERVICE INTEREST', 'Sales'],
  book_callback:             ['CALLBACK BOOKED', 'Sales'],
  check_registration_status: ['STATUS CHASE', 'Formations'],
  support_request:           ['SUPPORT', 'Support'],
  escalate_to_human:         ['ESCALATION', 'Manager'],
  take_message:              ['MESSAGE', 'Reception'],
};
const [label, team] = LABELS[tool] ?? ['CALL', 'Reception'];

// Anything the agent flagged as hot goes to the top of the subject line.
const hot = args.urgency === 'immediately'
  || args.urgency === 'within_hour'
  || args.urgency === 'urgent'
  || args.temperature === 'ready_now'
  || args.sentiment === 'frustrated'
  || tool === 'escalate_to_human';

const who = args.full_name || args.contact_name || args.candidate_name || 'Unknown caller';
const subject = `${hot ? '[URGENT] ' : ''}${label} — ${who}`;

// Print every field the agent captured, in a readable order, without
// inventing any it did not send.
const pretty = (k) => k.replace(/_/g, ' ').replace(/^\w/, (c) => c.toUpperCase());

// The service enum is machine-shaped. Nobody should have to read
// "5_page_website_399" over their morning coffee.
const SERVICES = {
  '5_page_website_399': '5 Page Website (\u00a3399)',
  ecommerce_website_999: 'E-Commerce Website (\u00a3999)',
  email_domain_setup_50: 'Email & Domain Setup (\u00a350)',
  branding_package_299: 'Branding Package (\u00a3299)',
  graphic_design_bundle_199: 'Graphic Design Bundle (\u00a3199)',
  promotional_video_99: 'Promotional Video (\u00a399)',
  promotional_video_bundle_299: 'Promotional Video Bundle (\u00a3299)',
  social_bronze_199_mo: 'Social Media Bronze (\u00a3199/mo)',
  social_silver_299_mo: 'Social Media Silver (\u00a3299/mo)',
  social_gold_399_mo: 'Social Media Gold (\u00a3399/mo)',
  social_vip_499_mo: 'Social Media VIP (\u00a3499/mo)',
  seo_bronze_99_mo: 'Bronze SEO (\u00a399/mo)',
  seo_silver_199_mo: 'Silver SEO (\u00a3199/mo)',
  seo_gold_299_mo: 'Gold SEO (\u00a3299/mo)',
  seo_vip_499_mo: 'VIP SEO (\u00a3499/mo)',
  appointment_setting_3000_mo: 'Outsourced Appointment Setting (\u00a33,000/mo)',
  business_starter_pack_799: 'Business Starter Pack (\u00a3799)',
  premium_starter_pack_1999: 'Premium Starter Pack (\u00a31,999)',
  ultimate_starter_pack_4999: 'Ultimate Starter Pack (\u00a34,999)',
  undecided: 'Undecided',
};
const value = (k, v) => {
  if (k === 'service') return SERVICES[v] ?? v;
  if (typeof v === 'boolean') return v ? 'yes' : 'no';
  if (typeof v === 'string' && /^[a-z]+(_[a-z0-9]+)+$/.test(v)) return v.replace(/_/g, ' ');
  return v;
};

const ORDER = ['full_name', 'contact_name', 'phone', 'email', 'company_name'];
const keys = [
  ...ORDER.filter((k) => args[k] !== undefined && args[k] !== ''),
  ...Object.keys(args).filter((k) => !ORDER.includes(k) && args[k] !== undefined && args[k] !== ''),
];
const lines = keys.map((k) => `${pretty(k)}: ${value(k, args[k])}`);

const text = [
  `${label}  —  route to: ${team}`,
  '',
  ...lines,
  '',
  '—',
  `Tool: ${tool}`,
  call.call_id ? `Call ID: ${call.call_id}` : null,
  call.from_number ? `From: ${call.from_number}` : null,
  `Logged: ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' })}`,
].filter(Boolean).join('\n');

// Ellie speaks this back to the caller, so it has to sound like a person.
// Never phrase it as a system status.
const REPLIES = {
  start_registration:        "That's with the formations team now.",
  log_service_interest:      "That's over to the team now.",
  book_callback:             "That's in the diary.",
  check_registration_status: "I've flagged that for someone to check.",
  support_request:           "That's logged with support now.",
  escalate_to_human:         "I've put that straight through to a manager.",
  take_message:              "That's passed on now.",
};

return [{ json: { to: TEAM_INBOX, subject, text, reply: REPLIES[tool] ?? 'That\u2019s logged now.' } }];
